package org.jlinalg.genetics;

import java.util.ArrayList;
import java.util.HashSet;
import java.util.List;
import java.util.Random;
import java.util.concurrent.atomic.AtomicInteger;
import org.jlinalg.genetics.FumaFisherGroups.*;
import org.jlinalg.genetics.FumaKnownAssociations.Decision;
import org.jlinalg.genetics.FumaKnownAssociations.Key;
import org.jlinalg.genetics.FumaKnownAssociations.Matching;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class FumaFisherGroupsTest {
    private static final Runnable CHECK=()->{};
    private static Observation row(int n,String source,String trait,String context,String gene,Decision decision){return new Observation(n,source,trait,context,new Key(gene,trait),decision);}
    private static final class Data {
        List<Observation> rows=new ArrayList<>(List.of(
            row(1,"B","T1","bulk","G1",Decision.KNOWN),row(2,"B","T1","bulk","G2",Decision.NOVEL_RELATIVE_TO_BASELINES),row(3,"B","T1","bulk","G3",Decision.TARGET_NOT_SELECTED),
            row(4,"F1","T1","EN","G1",Decision.KNOWN),row(5,"F1","T1","EN","G3",Decision.NOVEL_RELATIVE_TO_BASELINES),row(6,"F1","T1","EN","G3",Decision.NOVEL_RELATIVE_TO_BASELINES),row(7,"F1","T1","EN","G4",Decision.UNASSESSABLE_BASELINE),row(8,"F1","T1","EN","G5",Decision.MISSING_TARGET_VALUE),
            row(9,"F2","T1","IN","G1",Decision.KNOWN),row(10,"F2","T1","IN","G6",Decision.NOVEL_RELATIVE_TO_BASELINES),row(11,"F2","T2","IN","G2",Decision.NOVEL_RELATIVE_TO_BASELINES)));
        List<Group> groups=new ArrayList<>(List.of(new Group("bulk",List.of(new Member("B","T1","bulk",3))),new Group("finer",List.of(new Member("F1","T1","EN",5),new Member("F2","T1","IN",2),new Member("F2","T2","IN",1)))));
        Options options=new Options(Matching.GENE_TRAIT,Unassessable.EXCLUDE,Limits.defaults());
        Result run(Overlap policy){return FumaFisherGroups.count(rows,groups,List.of(new Comparison("F","test","labels-do-not-filter","comparison-label","finer","bulk",policy)),options,CHECK);}
    }
    @Test void geneTraitUnionsRetainEveryContributorAndExcludeUnavailableEvidence(){var r=new Data().run(Overlap.RETAIN_BOTH);assertEquals(new FumaFisherExact.Counts(3,1,1,1),r.tables().get(0).counts());assertEquals(11,r.dispositions().size());assertEquals(7,r.keys().size());assertEquals(List.of(4,9),r.keys().stream().filter(k->k.group().equals("finer")&&k.key().gene().equals("G1")).findFirst().orElseThrow().inputRows());assertEquals(List.of(5,6),r.keys().stream().filter(k->k.group().equals("finer")&&k.key().gene().equals("G3")).findFirst().orElseThrow().inputRows());assertEquals(1,r.groups().get(1).missingTargetRows());assertEquals(1,r.groups().get(1).unassessableKeys());assertEquals(1,r.groups().get(0).unselectedRows());assertTrue(r.unassigned().isEmpty());}
    @Test void finerOnlyRemovesAllSelectedComparatorKeysAndRetainsOverlapEvidence(){var r=new Data().run(Overlap.FINER_ONLY);assertEquals(new FumaFisherExact.Counts(3,0,1,1),r.tables().get(0).counts());assertEquals(1,r.sharedKeys().size());var shared=r.sharedKeys().get(0);assertEquals(new Key("G1","T1"),shared.key());assertEquals(List.of(4,9),shared.finerRows());assertEquals(List.of(1),shared.comparatorRows());assertTrue(shared.excludedFromFiner());assertEquals(Overlap.FINER_ONLY,shared.policy());}
    @Test void retainBothKeepsSharedKeysInBothTableRowsWithoutDuplicatingWithinGroup(){var r=new Data().run(Overlap.RETAIN_BOTH);assertEquals(1,r.tables().get(0).counts().finerKnown());assertEquals(1,r.tables().get(0).counts().comparatorKnown());assertFalse(r.sharedKeys().get(0).excludedFromFiner());assertEquals(2,r.sharedKeys().get(0).finerRows().size());}
    @Test void overlapErrorRefusesSharedSelectedKeys(){assertTrue(assertThrows(IllegalArgumentException.class,()->new Data().run(Overlap.ERROR)).getMessage().contains("Shared selected keys"));}
    @Test void changingMatchingRequiresRecomputedSourceKeys(){var d=new Data();d.options=new Options(Matching.GENE_ACROSS_TRAITS,Unassessable.EXCLUDE,Limits.defaults());assertTrue(assertThrows(IllegalArgumentException.class,()->d.run(Overlap.RETAIN_BOTH)).getMessage().contains("source classification keys"));var across=new ArrayList<Observation>();for(var o:d.rows)across.add(new Observation(o.inputRow(),o.source(),o.trait(),o.context(),new Key(o.key().gene(),null),o.decision()));d.rows=across;var r=d.run(Overlap.FINER_ONLY);assertEquals(new FumaFisherExact.Counts(2,0,1,1),r.tables().get(0).counts());assertEquals(2,r.sharedKeys().size());assertTrue(r.keys().stream().allMatch(k->k.key().trait()==null));}
    @Test void unavailableRowsRequireExplicitExclusion(){var d=new Data();d.options=new Options(Matching.GENE_TRAIT,Unassessable.ERROR,Limits.defaults());assertTrue(assertThrows(IllegalArgumentException.class,()->d.run(Overlap.RETAIN_BOTH)).getMessage().contains("EXCLUDE"));}
    @Test void memberCountsIncludeMissingAndUnselectedRows(){var d=new Data();d.groups.set(1,new Group("finer",List.of(new Member("F1","T1","EN",4),new Member("F2","T1","IN",2),new Member("F2","T2","IN",1))));assertTrue(assertThrows(IllegalArgumentException.class,()->d.run(Overlap.RETAIN_BOTH)).getMessage().contains("Incomplete declared group"));}
    @Test void selectedConflictingClassificationsWithinAKeyAreNeverRelabelled(){var d=new Data();var o=d.rows.get(5);d.rows.set(5,new Observation(o.inputRow(),o.source(),o.trait(),o.context(),o.key(),Decision.KNOWN));assertTrue(assertThrows(IllegalArgumentException.class,()->d.run(Overlap.RETAIN_BOTH)).getMessage().contains("Conflicting selected"));}
    @Test void comparedGroupsMustUseConsistentSharedKeyClassifications(){var d=new Data();var o=d.rows.get(0);d.rows.set(0,new Observation(o.inputRow(),o.source(),o.trait(),o.context(),o.key(),Decision.NOVEL_RELATIVE_TO_BASELINES));assertTrue(assertThrows(IllegalArgumentException.class,()->d.run(Overlap.FINER_ONLY)).getMessage().contains("Conflicting shared-key"));}
    @Test void duplicateOriginalRowsDomainsGroupsAndComparisonsAreRefused(){var d=new Data();d.rows.add(d.rows.get(0));Data duplicateRows=d;assertThrows(IllegalArgumentException.class,()->duplicateRows.run(Overlap.RETAIN_BOTH));d=new Data();d.groups.add(d.groups.get(0));Data duplicateGroup=d;assertThrows(IllegalArgumentException.class,()->duplicateGroup.run(Overlap.RETAIN_BOTH));d=new Data();d.groups.set(0,new Group("bulk",List.of(new Member("B","T1","bulk",3),new Member("B","T1","bulk",3))));Data duplicateDomain=d;assertThrows(IllegalArgumentException.class,()->duplicateDomain.run(Overlap.RETAIN_BOTH));var base=new Data();var comparison=new Comparison("F","x","t","c","finer","bulk",Overlap.RETAIN_BOTH);assertThrows(IllegalArgumentException.class,()->FumaFisherGroups.count(base.rows,base.groups,List.of(comparison,comparison),base.options,CHECK));}
    @Test void sameComparisonIdMayBeDeclaredInDifferentCorrectionFamilies(){var d=new Data();var r=FumaFisherGroups.count(d.rows,d.groups,List.of(new Comparison("A","x","t","c","finer","bulk",Overlap.RETAIN_BOTH),new Comparison("B","x","t","c","finer","bulk",Overlap.FINER_ONLY)),d.options,CHECK);assertEquals(List.of("A","B"),r.tables().stream().map(FumaFisherFamilies.Table::family).toList());assertNotEquals(r.tables().get(0).counts(),r.tables().get(1).counts());}
    @Test void explicitEmptyDomainsStayEmptyBeforePseudocounts(){var d=new Data();d.groups.add(new Group("empty",List.of(new Member("declared-source","T1","none",0))));var r=FumaFisherGroups.count(d.rows,d.groups,List.of(new Comparison("F","empty","T1","empty","empty","bulk",Overlap.ERROR)),d.options,CHECK);assertEquals(new FumaFisherExact.Counts(0,0,1,1),r.tables().get(0).counts());assertEquals(0,r.groups().get(2).actualRows());assertTrue(r.warnings().stream().anyMatch(s->s.contains("EMPTY ELIGIBLE GROUP")));}
    @Test void unassignedSourceRowsRemainVisibleWithTheirOriginalStatus(){var d=new Data();var extra=row(12,"outside","T3","outside","X",Decision.KNOWN);d.rows.add(extra);var r=d.run(Overlap.RETAIN_BOTH);assertEquals(List.of(extra),r.unassigned());assertEquals(11,r.dispositions().size());assertTrue(r.warnings().stream().anyMatch(s->s.contains("UNASSIGNED SOURCE ROWS")));}
    @Test void inputEvidenceAndWorkBudgetsRefuseWholeResults(){for(var limit:List.of(new Limits(14,1000,100000),new Limits(1000,1,100000),new Limits(1000,1000,1))){var d=new Data();d.options=new Options(Matching.GENE_TRAIT,Unassessable.EXCLUDE,limit);assertThrows(IllegalArgumentException.class,()->d.run(Overlap.RETAIN_BOTH));}}
    @Test void contributorAndOverlapPointersConsumeEvidenceCapacity(){var d=new Data();var full=d.run(Overlap.RETAIN_BOTH);assertEquals(35,full.evidence());d.options=new Options(Matching.GENE_TRAIT,Unassessable.EXCLUDE,new Limits(1000,34,100000));assertTrue(assertThrows(IllegalArgumentException.class,()->d.run(Overlap.RETAIN_BOTH)).getMessage().contains("contributors or overlaps"));}
    @Test void cancellationPropagatesWithoutReturningTruncatedGroups(){var d=new Data();assertThrows(IllegalStateException.class,()->FumaFisherGroups.count(d.rows,d.groups,List.of(),d.options,()->{throw new IllegalStateException("cancelled");}));var many=new ArrayList<Observation>();for(int i=1;i<=2000;i++)many.add(row(i,"S","T","C","G"+i,Decision.KNOWN));var calls=new AtomicInteger();assertThrows(IllegalStateException.class,()->FumaFisherGroups.count(many,List.of(new Group("G",List.of(new Member("S","T","C",2000)))),List.of(),new Options(Matching.GENE_TRAIT,Unassessable.ERROR,Limits.defaults()),()->{if(calls.incrementAndGet()>1)throw new IllegalStateException("cancelled during work");}));}
    private static FumaKnownAssociations.Result known(Matching matching){
        var sources=List.of(new FumaKnownAssociations.Source("M",FumaKnownAssociations.Role.BASELINE),new FumaKnownAssociations.Source("B",FumaKnownAssociations.Role.TARGET),new FumaKnownAssociations.Source("C",FumaKnownAssociations.Role.TARGET));
        var families=new ArrayList<FumaKnownAssociations.Family>();for(String id:List.of("M","B","C"))families.add(new FumaKnownAssociations.Family(id,id,List.of(new FumaKnownAssociations.Member("T1",id,id.equals("C")?4:3)),FumaKnownAssociations.Encoding.P_VALUE,FumaKnownAssociations.Adjustment.BH,id.equals("C")?FumaKnownAssociations.Missing.EXCLUDE:FumaKnownAssociations.Missing.ERROR,FumaKnownAssociations.ReportedZero.ERROR,FumaKnownAssociations.Duplicates.ERROR,"synthetic original test"));
        var rows=new ArrayList<FumaKnownAssociations.Test>();for(String source:List.of("M","B","C")){int n=source.equals("C")?4:3;for(int i=1;i<=n;i++)rows.add(new FumaKnownAssociations.Test(source,"id"+i,"G"+i,"T1",source,i==4?null:i==1?.001:source.equals("M")||source.equals("B")&&i==3?.9:.002));}
        return FumaKnownAssociations.review(sources,families,rows,new FumaKnownAssociations.Options(.05,matching,FumaKnownAssociations.Absence.SELECTED_REFERENCE,FumaKnownAssociations.Limits.defaults()),CHECK);
    }
    @Test void nativeKnownAssociationBridgePreservesAllTargetRowsAndUpstreamFamilies(){for(var matching:Matching.values()){var input=known(matching);var before=input.families();var bridge=FumaFisherGroups.fromKnown(input,Limits.defaults(),CHECK);assertEquals(7,bridge.observations().size());assertEquals(List.of(4,5,6,7,8,9,10),bridge.observations().stream().map(Observation::inputRow).toList());assertEquals(Decision.MISSING_TARGET_VALUE,bridge.observations().get(6).decision());var groups=List.of(new Group("bulk",List.of(new Member("B","T1","B",3))),new Group("finer",List.of(new Member("C","T1","C",4))));var counted=FumaFisherGroups.count(bridge.observations(),groups,List.of(new Comparison("F","one","T1","finer-only","finer","bulk",Overlap.FINER_ONLY)),new Options(matching,Unassessable.EXCLUDE,Limits.defaults()),CHECK);assertEquals(new FumaFisherExact.Counts(1,0,1,1),counted.tables().get(0).counts());assertEquals(before,input.families());assertTrue(bridge.operations()>0);}}
    @Test void bridgeRejectsMissingDuplicateAndNontargetDecisions(){var input=known(Matching.GENE_TRAIT);var reduced=new FumaKnownAssociations.Result(input.tests(),input.families(),input.known(),input.targets().subList(1,input.targets().size()),input.coverage(),input.links(),input.warnings(),input.operations());assertThrows(IllegalArgumentException.class,()->FumaFisherGroups.fromKnown(reduced,Limits.defaults(),CHECK));var targets=new ArrayList<>(input.targets());targets.add(targets.get(0));var duplicate=new FumaKnownAssociations.Result(input.tests(),input.families(),input.known(),targets,input.coverage(),input.links(),input.warnings(),input.operations());assertThrows(IllegalArgumentException.class,()->FumaFisherGroups.fromKnown(duplicate,Limits.defaults(),CHECK));targets=new ArrayList<>(input.targets());targets.set(0,new FumaKnownAssociations.TargetDecision(1,new Key("G1","T1"),Decision.KNOWN,1));var nonTarget=new FumaKnownAssociations.Result(input.tests(),input.families(),input.known(),targets,input.coverage(),input.links(),input.warnings(),input.operations());assertThrows(IllegalArgumentException.class,()->FumaFisherGroups.fromKnown(nonTarget,Limits.defaults(),CHECK));}
    @Test void bridgeRejectsForgedSelectionAndKeyProvenance(){var input=known(Matching.GENE_TRAIT);var rows=new ArrayList<>(input.tests());var a=rows.get(9);rows.set(9,new FumaKnownAssociations.Assessed(a.inputRow(),a.test(),a.source(),a.family(),a.adjustedP(),a.adjustedLogP(),true,a.duplicateOfInputRow(),a.disposition()));var forged=new FumaKnownAssociations.Result(rows,input.families(),input.known(),input.targets(),input.coverage(),input.links(),input.warnings(),input.operations());assertThrows(IllegalArgumentException.class,()->FumaFisherGroups.fromKnown(forged,Limits.defaults(),CHECK));var targets=new ArrayList<>(input.targets());var old=targets.get(0);targets.set(0,new FumaKnownAssociations.TargetDecision(old.inputRow(),new Key("wrong","T1"),old.decision(),old.matchedKnownTests()));var wrongKey=new FumaKnownAssociations.Result(input.tests(),input.families(),input.known(),targets,input.coverage(),input.links(),input.warnings(),input.operations());assertThrows(IllegalArgumentException.class,()->FumaFisherGroups.fromKnown(wrongKey,Limits.defaults(),CHECK));}
    @Test void bridgeCapacityAndOrderedProvenanceAreChecked(){var input=known(Matching.GENE_TRAIT);assertThrows(IllegalArgumentException.class,()->FumaFisherGroups.fromKnown(input,new Limits(16,1000,100000),CHECK));var rows=new ArrayList<>(input.tests());var a=rows.get(0);rows.set(0,new FumaKnownAssociations.Assessed(2,a.test(),a.source(),a.family(),a.adjustedP(),a.adjustedLogP(),a.selected(),a.duplicateOfInputRow(),a.disposition()));var unordered=new FumaKnownAssociations.Result(rows,input.families(),input.known(),input.targets(),input.coverage(),input.links(),input.warnings(),input.operations());assertThrows(IllegalArgumentException.class,()->FumaFisherGroups.fromKnown(unordered,Limits.defaults(),CHECK));}
    @Test void groupedTablesFeedCompleteFisherFamiliesWithOriginalCountsUnchanged(){var d=new Data();var comparisons=List.of(new Comparison("F","keep","T1","keep","finer","bulk",Overlap.RETAIN_BOTH),new Comparison("F","only","T1","only","finer","bulk",Overlap.FINER_ONLY));var grouped=FumaFisherGroups.count(d.rows,d.groups,comparisons,d.options,CHECK);var family=new FumaFisherFamilies.Family("F",List.of("keep","only"),FumaFisherFamilies.Correction.BH,FumaFisherFamilies.Encoding.NATURAL_LOG,FumaFisherFamilies.Missing.ERROR,FumaFisherFamilies.Empty.ERROR,1,.95);var fitted=FumaFisherFamilies.fit(List.of(family),grouped.tables(),new FumaFisherFamilies.Options(.05,FumaFisherFamilies.Limits.defaults()),CHECK);assertEquals(2,fitted.tables().size());assertEquals(2,fitted.families().get(0).adjustmentSize());for(int i=0;i<2;i++)assertEquals(grouped.tables().get(i).counts(),fitted.tables().get(i).fit().original());assertNotEquals(fitted.tables().get(0).fit().oddsRatio(),fitted.tables().get(1).fit().oddsRatio());}
    @Test void randomGroupCountsAgreeWithIndependentExhaustiveSetDefinitions(){var random=new Random(20261030);for(int trial=0;trial<250;trial++){
        boolean across=trial%2==0;var observations=new ArrayList<Observation>();var status=new Decision[12];for(int i=0;i<12;i++)status[i]=List.of(Decision.KNOWN,Decision.NOVEL_RELATIVE_TO_BASELINES,Decision.UNASSESSABLE_BASELINE).get(random.nextInt(3));int row=0;
        for(String source:List.of("B","F"))for(int gene=0;gene<12;gene++)for(int repeat=0;repeat<random.nextInt(4);repeat++){String trait="T"+(across?repeat%2:gene%2);var decision=random.nextInt(7)==0?Decision.MISSING_TARGET_VALUE:random.nextInt(5)==0?Decision.TARGET_NOT_SELECTED:status[gene];observations.add(new Observation(++row,source,trait,"C",new Key("G"+gene,across?null:trait),decision));}
        var groups=new ArrayList<Group>();for(String source:List.of("B","F")){var members=new ArrayList<Member>();for(String trait:List.of("T0","T1")){int n=0;for(var o:observations)if(o.source().equals(source)&&o.trait().equals(trait))n++;members.add(new Member(source,trait,"C",n));}groups.add(new Group(source,members));}
        for(var policy:List.of(Overlap.RETAIN_BOTH,Overlap.FINER_ONLY)){var fineKnown=new HashSet<Key>();var fineNovel=new HashSet<Key>();var bulkKnown=new HashSet<Key>();var bulkNovel=new HashSet<Key>();var selectedBulk=new HashSet<Key>();for(var o:observations){if(o.source().equals("B")&&o.decision()!=Decision.MISSING_TARGET_VALUE&&o.decision()!=Decision.TARGET_NOT_SELECTED)selectedBulk.add(o.key());if(o.decision()==Decision.KNOWN)(o.source().equals("F")?fineKnown:bulkKnown).add(o.key());if(o.decision()==Decision.NOVEL_RELATIVE_TO_BASELINES)(o.source().equals("F")?fineNovel:bulkNovel).add(o.key());}if(policy==Overlap.FINER_ONLY){fineKnown.removeAll(selectedBulk);fineNovel.removeAll(selectedBulk);}var r=FumaFisherGroups.count(observations,groups,List.of(new Comparison("family","test","labels","labels","F","B",policy)),new Options(across?Matching.GENE_ACROSS_TRAITS:Matching.GENE_TRAIT,Unassessable.EXCLUDE,Limits.defaults()),CHECK);assertEquals(new FumaFisherExact.Counts(fineNovel.size(),fineKnown.size(),bulkNovel.size(),bulkKnown.size()),r.tables().get(0).counts(),"trial "+trial+" "+policy);assertEquals(observations.size(),r.dispositions().size());assertTrue(r.unassigned().isEmpty());}
    }}
    @Test void invalidMembersModesAndGroupIdentitiesAreRefused(){assertThrows(IllegalArgumentException.class,()->new Group("G",List.of()));assertThrows(IllegalArgumentException.class,()->new Member("S","T","C",-1));assertThrows(IllegalArgumentException.class,()->new Comparison("F","x","T","C","same","same",Overlap.RETAIN_BOTH));assertThrows(IllegalArgumentException.class,()->row(0,"S","T","C","G",Decision.KNOWN));assertThrows(IllegalArgumentException.class,()->new Observation(1,"S","T","C",new Key("G","other"),Decision.KNOWN));assertThrows(IllegalArgumentException.class,()->new Options(null,Unassessable.ERROR,Limits.defaults()));var d=new Data();assertThrows(IllegalArgumentException.class,()->FumaFisherGroups.count(d.rows,d.groups,List.of(new Comparison("F","x","T","C","unknown","bulk",Overlap.ERROR)),d.options,CHECK));}
    @Test void groupResultsAndContributorListsAreImmutable(){var r=new Data().run(Overlap.RETAIN_BOTH);assertThrows(UnsupportedOperationException.class,()->r.tables().clear());assertThrows(UnsupportedOperationException.class,()->r.keys().clear());assertThrows(UnsupportedOperationException.class,()->r.keys().get(0).inputRows().clear());assertThrows(UnsupportedOperationException.class,()->r.sharedKeys().get(0).finerRows().clear());assertThrows(UnsupportedOperationException.class,()->r.unassigned().clear());assertTrue(r.warnings().stream().allMatch(s->s.contains("Required action:")));}
}
